package com.bank.quality.checks;

import com.bank.quality.model.Record;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Per-record checks: schema/null, range, uniqueness → bad records to DLQ.
public class QualityChecker {
    private static final Logger log = Logger.getLogger(QualityChecker.class.getName());
    private static final BigDecimal MAX = new BigDecimal("100000000");
    private final Set<String> seenIds = new HashSet<>();
    private final List<Record> deadLetterQueue = new ArrayList<>();

    public List<Record> check(List<Record> batch) {
        List<Record> good = new ArrayList<>();
        for (Record r : batch) {
            if (r.getRecordId() == null || r.getAccountId() == null || r.getAmount() == null) {
                    quarantine(r, "null mandatory field");
                    continue;
            }
            if (r.getAmount().compareTo(BigDecimal.ZERO) <= 0 || r.getAmount().compareTo(MAX) > 0) {
                    quarantine(r, "amount out of range");
                    continue;
            }
            if (!seenIds.add(r.getRecordId())) {
                    quarantine(r, "duplicate recordId");
                    continue;
            }
            good.add(r);
        }
        return good;
    }

    private void quarantine(Record r, String reason) {
        deadLetterQueue.add(r);
        log.warning(() -> "DLQ quarantine " + (r.getRecordId() == null ? "<null-id>" : r.getRecordId())
                + " reason=" + reason);
    }
    public int dlqSize() { return deadLetterQueue.size(); }
}
