package com.bank.quality.checks;

import com.bank.quality.model.Record;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Dataset-level checks: row count + total sum vs source expectation.
public class Reconciler {
    private static final Logger log = Logger.getLogger(Reconciler.class.getName());

    public boolean reconcile(long sourceRows, BigDecimal sourceTotal,
                             long loadedRows, BigDecimal loadedTotal) {
        boolean ok = sourceRows == loadedRows && sourceTotal.compareTo(loadedTotal) == 0;
        if (ok) {
            log.info("RECONCILE OK: rows=" + loadedRows + " total=" + loadedTotal);
        } else {
            log.severe("RECONCILE MISMATCH: source(rows=" + sourceRows + ",total=" + sourceTotal
                    + ") vs loaded(rows=" + loadedRows + ",total=" + loadedTotal + ") → FAIL BATCH + ALERT");
        }
        return ok;
    }
}
