package com.bank.quality.target;

import com.bank.quality.model.Record;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Idempotent target: upsert by recordId so re-runs/backfills never duplicate.
public class IdempotentTarget {
    private static final Logger log = Logger.getLogger(IdempotentTarget.class.getName());
    private final Map<String, Record> table = new LinkedHashMap<>();

    public void upsertAll(List<Record> records) {
        for (Record r : records) table.put(r.getRecordId(), r);
        log.info("UPSERT " + records.size() + " records; target now has " + table.size());
    }
    public long rowCount() { return table.size(); }
    public BigDecimal total() {
        BigDecimal t = BigDecimal.ZERO;
        for (Record r : table.values()) t = t.add(r.getAmount());
        return t;
    }
}
