package com.bank.quality;

import com.bank.quality.checks.*;
import com.bank.quality.model.Record;
import com.bank.quality.target.IdempotentTarget;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

public class QualityDemo {
    private static final Logger log = Logger.getLogger(QualityDemo.class.getName());

    public static void main(String[] args) {
        QualityChecker checker = new QualityChecker();
        Reconciler reconciler = new Reconciler();
        IdempotentTarget target = new IdempotentTarget();

        // Source batch (incl bad records). Assume source EXPECTS 3 valid rows totalling 7700.
        List<Record> batch = new ArrayList<>(List.of(
            new Record("R1", "SAV2001", new BigDecimal("1200")),
            new Record("R2", "CUR3001", new BigDecimal("5000")),
            new Record("R1", "SAV2001", new BigDecimal("1200")), // duplicate
            new Record("R4", "SAV2001", null),                   // null amount
            new Record("R5", "CUR3001", new BigDecimal("-10"))   // out of range
            // Note: R3 (1500) was MISSED by the source feed this run.
        ));

        log.info("=== Run 1: quality checks ===");
        List<Record> good = checker.check(batch);
        target.upsertAll(good);
        log.info("DLQ size = " + checker.dlqSize());

        log.info("=== Reconcile against source expectation (3 rows, 7700) ===");
        boolean ok = reconciler.reconcile(3, new BigDecimal("7700"), target.rowCount(), target.total());
        if (!ok) log.severe("Batch failed reconciliation → investigate & backfill");

        log.info("=== Backfill missed R3, then safe re-run (idempotent) ===");
        QualityChecker checker2 = new QualityChecker(); // fresh uniqueness scope for backfill
        List<Record> backfill = checker2.check(List.of(new Record("R3", "SAV2001", new BigDecimal("1500"))));
        target.upsertAll(backfill);
        target.upsertAll(good); // replay good batch again — must NOT duplicate

        log.info("=== Reconcile after backfill ===");
        reconciler.reconcile(3, new BigDecimal("7700"), target.rowCount(), target.total());
    }
}
